-- Deterministic synthetic reference data. Shipment-level volume is generated by scripts/seed_data.py.
VALUES ('ADMIN'), ('USER')
ON CONFLICT (role_name) DO NOTHING;

ON CONFLICT (customer_code) DO NOTHING;

ON CONFLICT (hub_code) DO NOTHING;

ON CONFLICT (registration_no) DO NOTHING;

ON CONFLICT (driver_code) DO NOTHING;

ON CONFLICT (route_code) DO NOTHING;

-- Keep identity sequences ahead of the explicit reference IDs.
SELECT setval(pg_get_serial_sequence('customers','customer_id'), COALESCE((SELECT MAX(customer_id) FROM customers), 1));
SELECT setval(pg_get_serial_sequence('hubs','hub_id'), COALESCE((SELECT MAX(hub_id) FROM hubs), 1));
SELECT setval(pg_get_serial_sequence('vehicles','vehicle_id'), COALESCE((SELECT MAX(vehicle_id) FROM vehicles), 1));
SELECT setval(pg_get_serial_sequence('drivers','driver_id'), COALESCE((SELECT MAX(driver_id) FROM drivers), 1));
SELECT setval(pg_get_serial_sequence('routes','route_id'), COALESCE((SELECT MAX(route_id) FROM routes), 1));
